import java.util.*;
import java.io.*;

public class MazeFlow {
    static final int MAXN = 200;
    static final int MAXM = 100000;
    static final int INF = 200000000;

    static int[][] maze = new int[20][20];
    static int[][] graph = new int[MAXN][MAXN];
    static int n, N, t;
    static String s;
    static int[][] hu = new int[MAXN][3], re = new int[MAXN][3];
    static int zr, zc;
    static int cx, cy;
    static int[][] directions = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

    static int getIndex(int r, int c) {
        if (r > 0 && r <= n && c > 0 && c <= n && maze[r][c] != -1)
            return (r - 1) * n + c;
        return -1;
    }

    static void buildGraph() {
        N = n * n;
        for (int[] row : graph)
            Arrays.fill(row, -1);
        for (int r1 = 1; r1 <= n; r1++) {
            for (int c1 = 1; c1 <= n; c1++) {
                if (maze[r1][c1] == -1) continue;
                int p1 = (r1 - 1) * n + c1;
                graph[p1][p1] = 0;
                for (int i = 0; i < 4; i++) {
                    int r2 = r1 + directions[i][0];
                    int c2 = c1 + directions[i][1];
                    if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && maze[r2][c2] != -1) {
                        int p2 = (r2 - 1) * n + c2;
                        graph[p1][p2] = 1;
                    }
                }
            }
        }
    }

    static int[] dist = new int[MAXN];
    static int[] queue = new int[MAXM];

    static void shortestPath() {
        int front = 0, rear = 1;
        Arrays.fill(dist, INF);
        int start = (zr - 1) * n + zc;
        dist[start] = 0;
        queue[0] = start;
        while (front < rear) {
            int current = queue[front++];
            for (int i = 1; i <= N; i++) {
                if (graph[current][i] == 1 && dist[i] > dist[current] + 1) {
                    dist[i] = dist[current] + 1;
                    queue[rear++] = i;
                }
            }
        }
    }

    static void floydWarshall() {
        for (int k = 1; k <= N; k++) {
            for (int i = 1; i <= N; i++) {
                for (int j = 1; j <= N; j++) {
                    if (graph[i][k] != -1 && graph[k][j] != -1) {
                        if (graph[i][j] == -1 || graph[i][j] > graph[i][k] + graph[k][j]) {
                            graph[i][j] = graph[i][k] + graph[k][j];
                        }
                    }
                }
            }
        }
    }

    static class Edge {
        int st, ed, flow, next;
        public Edge(int st, int ed, int flow, int next) {
            this.st = st;
            this.ed = ed;
            this.flow = flow;
            this.next = next;
        }
    }

    static ArrayList<Edge> edges = new ArrayList<>();
    static int[] head = new int[MAXN];
    static int edgeCount;
    static int source, sink;

    static void addEdge(int st, int ed, int flow) {
        edges.add(new Edge(st, ed, flow, head[st]));
        head[st] = edges.size() - 1;
        edges.add(new Edge(ed, st, 0, head[ed]));
        head[ed] = edges.size() - 1;
    }

    static int[] level = new int[MAXN];

    static boolean bfs() {
        Arrays.fill(level, -1);
        level[source] = 0;
        int front = 0, rear = 1;
        queue[0] = source;
        while (front < rear) {
            int u = queue[front++];
            for (int i = head[u]; i != -1; i = edges.get(i).next) {
                Edge e = edges.get(i);
                int v = e.ed;
                if (e.flow > 0 && level[v] == -1) {
                    level[v] = level[u] + 1;
                    queue[rear++] = v;
                }
            }
        }
        return level[sink] != -1;
    }

    static int[] ptr = new int[MAXN];

    static int dfs(int u, int flow) {
        if (u == sink) return flow;
        for (int &i = ptr[u]; i != -1; i = edges.get(i).next) {
            Edge e = edges.get(i);
            int v = e.ed;
            if (e.flow > 0 && level[v] == level[u] + 1) {
                int pushed = dfs(v, Math.min(flow, e.flow));
                if (pushed > 0) {
                    e.flow -= pushed;
                    edges.get(i ^ 1).flow += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int total = 0;
        while (bfs()) {
            for (int i = 0; i <= N + 1; i++) {
                ptr[i] = head[i];
            }
            int pushed;
            while ((pushed = dfs(source, INF)) > 0) {
                total += pushed;
            }
        }
        return total;
    }

    static int solve() {
        maze[zr][zc] = 0;
        buildGraph();
        shortestPath();
        maze[zr][zc] = -1;
        buildGraph();
        floydWarshall();
        edges.clear();
        Arrays.fill(head, -1);
        edgeCount = 0;
        source = 0;
        sink = cx + cy + 1;
        for (int i = 1; i <= cx; i++) {
            addEdge(source, i, hu[i][2]);
        }
        for (int i = 1; i <= cy; i++) {
            addEdge(cx + i, sink, re[i][2]);
        }
        int p = (zr - 1) * n + zc;
        for (int i = 1; i <= cx; i++) {
            for (int j = 1; j <= cy; j++) {
                int p1 = (hu[i][0] - 1) * n + hu[i][1];
                int p2 = (re[j][0] - 1) * n + re[j][1];
                if (graph[p1][p2] != -1 && graph[p1][p2] <= t && graph[p1][p2] < dist[p2]) {
                    addEdge(i, cx + j, INF);
                } else if (graph[p1][p2] != -1 && graph[p1][p2] <= t && graph[p1][p2] == dist[p2]) {
                    for (int z = 0; z < 4; z++) {
                        int rr = re[j][0] + directions[z][0];
                        int cc = re[j][1] + directions[z][1];
                        int pp = getIndex(rr, cc);
                        if (pp != -1) {
                            if (graph[p1][pp] == graph[p1][p2] - 1 && graph[p1][pp] < dist[pp]) {
                                addEdge(i, cx + j, INF);
                            }
                        }
                    }
                }
            }
        }
        return maxFlow();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        cx = 0;
        cy = 0;
        for (int[] row : maze)
            Arrays.fill(row, 0);
        for (int i = 1; i <= n; i++) {
            s = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = s.charAt(j);
                if (ch == 'Y') maze[i][j + 1] = -1;
                else if (ch == 'Z') {
                    zr = i;
                    zc = j + 1;
                    maze[i][j + 1] = -1;
                } else if (ch > '0' && ch <= '9') {
                    hu[++cx][0] = i;
                    hu[cx][1] = j + 1;
                    hu[cx][2] = ch - '0';
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            s = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = s.charAt(j);
                if (ch > '0' && ch <= '9') {
                    re[++cy][0] = i;
                    re[cy][1] = j + 1;
                    re[cy][2] = ch - '0';
                }
            }
        }
        System.out.println(solve());
    }
}
